"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

export async function updateAppearanceSettings(formData: FormData) {
  const dashboardTheme = formData.get("dashboardTheme") as string;
  const dashboardFont = formData.get("dashboardFont") as string;
  const dashboardCustomColor = formData.get("dashboardCustomColor") as string | null;

  if (!dashboardTheme || !dashboardFont) {
    throw new Error("Missing required fields");
  }

  await prisma.platformSetting.upsert({
    where: { id: "1" },
    update: {
      dashboardTheme,
      dashboardFont,
      dashboardCustomColor: dashboardCustomColor || null,
    },
    create: {
      id: "1",
      dashboardTheme,
      dashboardFont,
      dashboardCustomColor: dashboardCustomColor || null,
    },
  });

  revalidatePath("/", "layout");
  redirect("/admin/appearance?success=true");
}

import { prisma } from "@/lib/prisma";
import Link from "next/link";
import { AppearanceClient } from "./AppearanceClient";

export const metadata = {
  title: "المظهر العام | لوحة الأدمن",
};

export default async function AdminAppearancePage() {
  let settings = null;

  try {
    settings = await prisma.platformSetting.findUnique({
      where: { id: "1" },
    });
  } catch (e) {
    console.warn("PlatformSetting missing or DB error", e);
  }

  const currentTheme = settings?.dashboardTheme || "blue";
  const currentFont = settings?.dashboardFont || "cairo";
  const currentCustomColor = settings?.dashboardCustomColor || null;

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-2 text-sm text-surface-500 font-medium">
          <Link href="/admin" className="hover:text-primary-600 transition-colors">الرئيسية</Link>
          <span>/</span>
          <span className="text-surface-900 font-semibold">المظهر العام للوحات التحكم</span>
        </div>
      </div>

      <AppearanceClient 
        initialTheme={currentTheme} 
        initialFont={currentFont} 
        initialCustomColor={currentCustomColor}
      />
    </div>
  );
}

"use server";

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { uploadImageToCloudinary } from "@/lib/upload";

export async function toggleStoreDefaultProducts(storeId: string, currentStatus: boolean) {
  const session = await auth();
  if (!session?.user || session.user.role !== "ADMIN") {
    return { error: "غير مصرح لك بالقيام بهذه العملية" };
  }

  try {
    await prisma.store.update({
      where: { id: storeId },
      data: { showDefaultProducts: !currentStatus },
    });

    revalidatePath("/admin/default-products");

    return { success: "تم تحديث إعدادات المتجر بنجاح" };
  } catch (error) {
    console.error("Toggle Store Default Products Error:", error);
    return { error: "حدث خطأ أثناء تحديث الإعدادات" };
  }
}

export async function createDefaultCategory(formData: FormData) {
  const session = await auth();
  if (!session?.user || session.user.role !== "ADMIN") return { error: "غير مصرح" };

  const name = formData.get("name") as string;
  const description = formData.get("description") as string;
  const sortOrder = parseInt(formData.get("sortOrder") as string) || 0;

  let image = null;
  const imageFile = formData.get("imageFile") as File | null;
  if (imageFile && imageFile.size > 0) {
    try {
      image = (await uploadImageToCloudinary(imageFile)) as string;
    } catch (e) {
      console.error("Upload error", e);
      return { error: "فشل رفع الصورة" };
    }
  }

  await prisma.category.create({
    data: { name, description, image, sortOrder, storeId: 'DEFAULT_STORE' }
  });
  revalidatePath("/admin/default-products");
}

export async function toggleDefaultCategoryStatus(categoryId: string, currentStatus: boolean) {
  const session = await auth();
  if (!session?.user || session.user.role !== "ADMIN") return;

  await prisma.category.update({
    where: { id: categoryId },
    data: { isActive: !currentStatus }
  });
  revalidatePath("/admin/default-products");
}

export async function deleteDefaultCategory(categoryId: string) {
  const session = await auth();
  if (!session?.user || session.user.role !== "ADMIN") return;

  await prisma.category.deleteMany({
    where: { id: categoryId, storeId: 'DEFAULT_STORE' }
  });
  revalidatePath("/admin/default-products");
}

export async function editDefaultCategory(formData: FormData) {
  const session = await auth();
  if (!session?.user || session.user.role !== "ADMIN") return { error: "غير مصرح" };

  const categoryId = formData.get("categoryId") as string;
  const name = formData.get("name") as string;
  const description = formData.get("description") as string;
  const sortOrder = parseInt(formData.get("sortOrder") as string) || 0;

  if (!name) return { error: "الاسم مطلوب" };

  const imageFile = formData.get("imageFile") as File | null;
  let image = undefined;

  if (imageFile && imageFile.size > 0) {
    try {
      image = (await uploadImageToCloudinary(imageFile)) as string;
    } catch (e) {
      console.error("Upload error", e);
      return { error: "فشل رفع الصورة" };
    }
  }

  try {
    await prisma.category.updateMany({
      where: { id: categoryId, storeId: "DEFAULT_STORE" },
      data: {
        name,
        description,
        sortOrder,
        ...(image !== undefined && { image })
      }
    });

    revalidatePath("/admin/default-products");
    return { success: true };
  } catch (error: any) {
    return { error: "حدث خطأ أثناء تعديل القسم" };
  }
}

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { Breadcrumb } from "@/components/dashboard/Breadcrumb";
import { Plus, PackageSearch, Store, Pencil } from "lucide-react";
import { MenuItemForm } from "@/components/dashboard/MenuItemForm";
import { AIMenuScanner } from "@/components/dashboard/AIMenuScanner";
import { MenuItemsTable } from "@/components/dashboard/MenuItemsTable";
import { SubmitButton } from "@/components/dashboard/SubmitButton";
import { DeleteConfirmButton } from "@/components/dashboard/DeleteConfirmButton";
import { DefaultCategoryForm } from "./DefaultCategoryForm";
import { createDefaultCategory, toggleDefaultCategoryStatus, deleteDefaultCategory } from "./actions";
import { OptimisticToggle } from "@/components/dashboard/OptimisticToggle";
import { DefaultProductsTabs } from "./DefaultProductsTabs";
import { ImageUpload } from "@/components/dashboard/ImageUpload";
import Link from "next/link";

export const metadata = {
  title: "المنتجات الافتراضية | لوحة الإدارة",
};

export const maxDuration = 60;

import { connection } from "next/server";

export default async function DefaultProductsPage(props: {
  searchParams: Promise<{ tab?: string; edit?: string; editCategory?: string }>;
}) {
  await connection();
  const searchParams = await props.searchParams;
  const session = await auth();

  if (!session?.user || session.user.role !== "ADMIN") {
    return null;
  }

  // Ensure DEFAULT_STORE and its user exists
  const systemUser = await prisma.user.upsert({
    where: { email: 'system@almenu.pro' },
    update: {},
    create: {
      email: 'system@almenu.pro',
      name: 'System Admin',
      password: 'none', // Dummy password, cannot login
      role: 'ADMIN',
      status: 'ACTIVE',
    }
  });

  await prisma.store.upsert({
    where: { id: 'DEFAULT_STORE' },
    update: {},
    create: {
      id: 'DEFAULT_STORE',
      name: 'المنتجات الافتراضية (النظام)',
      subdomain: 'default-system-template',
      userId: systemUser.id,
      type: 'RESTAURANT',
      showDefaultProducts: false, // System store itself doesn't show defaults
    }
  });

  const currentTab = searchParams.tab || 'menu';
  const editId = searchParams.edit;

  let editItem = null;
  if (editId) {
    editItem = await prisma.menuItem.findFirst({
      where: { id: editId as string, storeId: 'DEFAULT_STORE' },
      include: { sizes: true, addons: true }
    });
  }

  const editCategoryId = searchParams.editCategory;
  let editCategory = null;
  if (editCategoryId) {
    editCategory = await prisma.category.findFirst({
      where: { id: editCategoryId as string, storeId: 'DEFAULT_STORE' }
    });
  }

  // Fetch DEFAULT_STORE data
  const [menuItems, categories, allStores] = await Promise.all([
    prisma.menuItem.findMany({
      where: { storeId: 'DEFAULT_STORE' },
      orderBy: [
        { category: { sortOrder: 'asc' } },
        { sortOrder: 'asc' },
        { createdAt: 'asc' },
        { id: 'asc' }
      ],
      include: { category: true, sizes: true, addons: true }
    }),
    prisma.category.findMany({
      where: { storeId: 'DEFAULT_STORE' },
      orderBy: { sortOrder: 'asc' },
      include: { _count: { select: { items: true } } }
    }),
    prisma.store.findMany({
      where: { id: { not: 'DEFAULT_STORE' } },
      select: {
        id: true,
        name: true,
        subdomain: true,
        showDefaultProducts: true,
        categories: { select: { id: true } }
      },
      orderBy: { createdAt: 'desc' }
    })
  ]);

  return (
    <div className="animate-fade-in pb-10">
      <Breadcrumb title="إدارة المنتجات الافتراضية" />

      <p className="text-surface-500 mt-2 mb-6">
        هنا يمكنك إضافة أصناف وأقسام تظهر تلقائياً للمتاجر الجديدة، ويمكنك التحكم في تفعيل أو إيقاف هذه الميزة لكل متجر.
      </p>

      <DefaultProductsTabs currentTab={currentTab} />

      {currentTab === 'menu' && (
        <div className="mt-6 animate-fade-in">
          <div className="flex justify-end px-1 mb-6">
            <AIMenuScanner storeId="DEFAULT_STORE" />
          </div>

          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
            {/* نموذج إضافة صنف */}
            <div className="xl:col-span-1">
              <div className="bg-surface-50 rounded-[32px] border-2 border-surface-100 p-6 sticky top-6 max-h-[calc(100vh-2rem)] overflow-y-auto scrollbar-hide">
                <h3 className="text-xl font-black text-surface-950 mb-6 flex items-center gap-2">
                  <Plus className="w-6 h-6 text-primary-500" />
                  {editItem ? "تعديل الصنف الافتراضي" : "إضافة صنف افتراضي"}
                </h3>

                {categories.length === 0 ? (
                  <div className="p-5 bg-primary-50 text-primary-800 rounded-[24px] font-bold border-2 border-primary-100 mb-6">
                    يجب إضافة قسم واحد على الأقل للمتجر الافتراضي لكي تتمكن من إضافة أصناف.
                  </div>
                ) : null}

                <MenuItemForm 
                  key={editItem ? editItem.id : 'new'}
                  storeId="DEFAULT_STORE"
                  categories={categories.map(c => ({ id: c.id, name: c.name }))} 
                  initialData={editItem ? {
                    ...editItem,
                    price: editItem.price.toString(),
                    sizes: editItem.sizes.map((s: any) => ({ ...s, price: s.price.toString() })),
                    addons: editItem.addons.map((a: any) => ({ ...a, price: a.price.toString() }))
                  } : undefined}
                />
              </div>
            </div>

            {/* قائمة الأصناف */}
            <div className="xl:col-span-2">
              <MenuItemsTable 
                storeId="DEFAULT_STORE"
                menuItems={menuItems} 
                categories={categories.map(c => ({ id: c.id, name: c.name }))} 
              />
            </div>
          </div>
        </div>
      )}

      {currentTab === 'categories' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-6 animate-fade-in">
          {/* Add Category Form */}
          <div className="lg:col-span-1">
            <DefaultCategoryForm editCategory={editCategory} />
          </div>

          {/* Categories List */}
          <div className="lg:col-span-2">
            <div className="bg-white rounded-[24px] border border-surface-200 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-start">
                  <thead>
                    <tr className="bg-surface-50 border-b border-surface-200">
                      <th className="px-6 py-4 text-start text-sm font-bold text-surface-950">اسم القسم</th>
                      <th className="px-6 py-4 text-start text-sm font-bold text-surface-950">عدد الأصناف</th>
                      <th className="px-6 py-4 text-start text-sm font-bold text-surface-950">الحالة</th>
                      <th className="px-6 py-4 text-end text-sm font-bold text-surface-950">الإجراءات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-surface-100">
                    {categories.length === 0 ? (
                      <tr><td colSpan={4} className="px-6 py-8 text-center text-surface-500">لا يوجد أقسام بعد.</td></tr>
                    ) : (
                      categories.map((category: any) => (
                        <tr key={category.id} className="hover:bg-surface-50/50 transition-colors">
                          <td className="px-6 py-4">
                            <p className="font-bold text-surface-950">{category.name}</p>
                            {category.description && <p className="text-xs text-surface-500 mt-1 line-clamp-1">{category.description}</p>}
                          </td>
                          <td className="px-6 py-4"><span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-surface-100 text-surface-800">{category._count?.items || 0} أصناف</span></td>
                          <td className="px-6 py-4">
                            <OptimisticToggle 
                              initialStatus={category.isActive} 
                              action={async (status) => {
                                "use server";
                                return await toggleDefaultCategoryStatus(category.id, !status) as any;
                              }} 
                            />
                          </td>
                          <td className="px-6 py-4">
                            <div className="flex items-center justify-end gap-2">
                              <Link 
                                href={`/admin/default-products?tab=categories&editCategory=${category.id}`}
                                className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-surface-100 transition-colors text-surface-500"
                                title="تعديل القسم"
                              >
                                <Pencil className="w-4 h-4" />
                              </Link>
                              <DeleteConfirmButton action={deleteDefaultCategory.bind(null, category.id) as any} />
                            </div>
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      )}

      {currentTab === 'stores' && (
        <div className="mt-6 bg-white rounded-[24px] border border-surface-200 overflow-hidden animate-fade-in">
          <div className="overflow-x-auto">
            <table className="w-full text-start">
              <thead>
                <tr className="bg-surface-50 border-b border-surface-200">
                  <th className="px-6 py-4 text-start text-sm font-bold text-surface-950">المتجر</th>
                  <th className="px-6 py-4 text-start text-sm font-bold text-surface-950">الأقسام الحالية</th>
                  <th className="px-6 py-4 text-start text-sm font-bold text-surface-950">حالة المنتجات الافتراضية</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-surface-100">
                {allStores.map((store) => (
                  <tr key={store.id} className="hover:bg-surface-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-lg bg-primary-50 text-primary-600 flex items-center justify-center">
                          <Store className="w-5 h-5" />
                        </div>
                        <div>
                          <p className="font-bold text-surface-950">{store.name}</p>
                          <p className="text-xs text-surface-500 dir-ltr text-left">
                            {store.subdomain}.almenu.pro
                          </p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center justify-center px-2 py-1 rounded-full text-xs font-bold bg-surface-100 text-surface-600">
                        {store.categories.length} أقسام
                      </span>
                      {store.categories.length > 0 && (
                        <p className="text-xs text-surface-400 mt-1">المنتجات الافتراضية مخفية حالياً (بسبب وجود أقسام خاصة)</p>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <OptimisticToggle
                        initialStatus={store.showDefaultProducts}
                        action={async (status) => {
                          "use server";
                          const { toggleStoreDefaultProducts } = await import("./actions");
                          return await toggleStoreDefaultProducts(store.id, !status) as any;
                        }}
                      />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

"use server";

import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function getAdminNotifications() {
  const session = await auth();
  if (session?.user?.role !== "ADMIN") throw new Error("Unauthorized");

  const unreadCount = await prisma.adminNotification.count({
    where: { isRead: false },
  });

  const recent = await prisma.adminNotification.findMany({
    orderBy: { createdAt: "desc" },
    take: 5,
  });

  return { unreadCount, recent };
}

export async function markAdminNotificationAsRead(id: string) {
  const session = await auth();
  if (session?.user?.role !== "ADMIN") throw new Error("Unauthorized");

  await prisma.adminNotification.update({
    where: { id },
    data: { isRead: true },
  });

  revalidatePath("/admin");
  return { success: true };
}

export async function markAllAdminNotificationsAsRead() {
  const session = await auth();
  if (session?.user?.role !== "ADMIN") throw new Error("Unauthorized");

  await prisma.adminNotification.updateMany({
    where: { isRead: false },
    data: { isRead: true },
  });

  revalidatePath("/admin");
  return { success: true };
}

import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import { Bell, UserPlus, Info, CheckCheck } from "lucide-react";
import Link from "next/link";
import { revalidatePath } from "next/cache";

export const metadata = {
  title: "الإشعارات | لوحة الأدمن",
};

export default async function AdminNotificationsPage() {
  const session = await auth();
  if (session?.user?.role !== "ADMIN") return null;

  const notifications = await prisma.adminNotification.findMany({
    orderBy: { createdAt: "desc" },
    take: 100, // Fetch the last 100 notifications for this page
  });

  const markAllAsRead = async () => {
    "use server";
    const session = await auth();
    if (session?.user?.role === "ADMIN") {
      await prisma.adminNotification.updateMany({
        where: { isRead: false },
        data: { isRead: true },
      });
      revalidatePath("/admin/notifications");
    }
  };

  const getTimeAgo = (date: Date) => {
    const diff = Math.floor((new Date().getTime() - new Date(date).getTime()) / 1000);
    if (diff < 60) return "الآن";
    if (diff < 3600) return `منذ ${Math.floor(diff / 60)} دقيقة`;
    if (diff < 86400) return `منذ ${Math.floor(diff / 3600)} ساعة`;
    return `منذ ${Math.floor(diff / 86400)} يوم`;
  };

  const unreadCount = notifications.filter(n => !n.isRead).length;

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex items-center gap-2 text-sm text-surface-500 font-medium">
          <Link href="/admin" className="hover:text-primary-600 transition-colors">الرئيسية</Link>
          <span>/</span>
          <span className="text-surface-900 font-semibold">الإشعارات</span>
        </div>
      </div>

      <div className="bg-white rounded-[24px] border border-surface-200 overflow-hidden">
        <div className="p-6 border-b border-surface-100 flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold text-surface-950 flex items-center gap-2">
              <Bell className="w-6 h-6 text-primary-500" />
              كل الإشعارات
            </h1>
            <p className="text-surface-800/60 mt-1">
              سجل كامل لجميع التنبيهات والأحداث على المنصة.
            </p>
          </div>
          {unreadCount > 0 && (
            <form action={markAllAsRead}>
              <button
                type="submit"
                className="hidden sm:flex items-center gap-2 px-4 py-2 bg-primary-50 text-primary-700 font-medium rounded-[24px] hover:bg-primary-100 transition-colors"
              >
                <CheckCheck className="w-5 h-5" />
                تحديد الكل كمقروء
              </button>
            </form>
          )}
        </div>

        {notifications.length === 0 ? (
          <div className="p-16 text-center text-surface-500 flex flex-col items-center justify-center gap-4">
            <div className="w-20 h-20 rounded-full bg-surface-50 flex items-center justify-center">
              <Bell className="w-10 h-10 text-surface-300" />
            </div>
            <p className="text-lg font-semibold text-surface-900">لا توجد إشعارات حتى الآن</p>
            <p className="text-sm">لم يقم النظام بتسجيل أي أحداث بعد.</p>
          </div>
        ) : (
          <div className="divide-y divide-surface-100">
            {notifications.map((notif) => (
              <div
                key={notif.id}
                className={`p-6 hover:bg-surface-50 transition-colors flex gap-4 ${!notif.isRead ? 'bg-primary-50/20' : ''}`}
              >
                <div className={`w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 ${notif.type === 'NEW_USER' ? 'bg-primary-100 text-primary-600' : 'bg-surface-100 text-surface-600'}`}>
                  {notif.type === 'NEW_USER' ? <UserPlus className="w-6 h-6" /> : <Info className="w-6 h-6" />}
                </div>
                <div className="flex-1 min-w-0 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                  <div>
                    <h3 className={`text-base truncate ${!notif.isRead ? 'font-bold text-surface-950' : 'font-medium text-surface-800'}`}>
                      {notif.title}
                    </h3>
                    <p className={`text-sm mt-1 ${!notif.isRead ? 'text-surface-700 font-medium' : 'text-surface-600'}`}>
                      {notif.message}
                    </p>
                    <p className="text-xs text-surface-400 mt-2 font-medium" dir="ltr">
                      {getTimeAgo(notif.createdAt)} • {new Date(notif.createdAt).toLocaleDateString('ar-EG')}
                    </p>
                  </div>
                  <div className="flex items-center gap-3">
                    {notif.link && (
                      <Link
                        href={notif.link}
                        className="px-4 py-2 bg-white border border-surface-200 text-surface-700 text-sm font-medium rounded-[24px] hover:bg-surface-50 transition-colors whitespace-nowrap "
                      >
                        عرض التفاصيل
                      </Link>
                    )}
                    {!notif.isRead && (
                      <div className="w-2.5 h-2.5 rounded-full bg-primary-500 " title="غير مقروء" />
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";

export async function processPaymentRequestAction(
  requestId: string,
  storeId: string,
  planId: string,
  status: "APPROVED" | "REJECTED"
) {
  try {
    const adminId = "admin-1"; // TODO: get from Auth.js session

    // 1. Update the Payment Request
    await prisma.paymentRequest.update({
      where: { id: requestId },
      data: {
        status,
        reviewedBy: adminId,
        reviewedAt: new Date()
      }
    });

    if (status === "APPROVED") {
      const plan = await prisma.plan.findUnique({ where: { id: planId } });
      if (!plan) throw new Error("الباقة غير موجودة");

      const startDate = new Date();
      const endDate = new Date();
      endDate.setDate(endDate.getDate() + plan.durationDays);

      // 2. Upsert Subscription
      await prisma.subscription.upsert({
        where: { storeId },
        update: {
          planId: plan.id,
          status: "ACTIVE",
          startDate,
          endDate
        },
        create: {
          storeId,
          planId: plan.id,
          status: "ACTIVE",
          startDate,
          endDate
        }
      });

      // 3. Add History
      await prisma.subscriptionHistory.create({
        data: {
          storeId,
          action: "PAYMENT_APPROVED",
          details: `تم تفعيل باقة ${plan.name} لمدة ${plan.durationDays} يوم`
        }
      });

      // 4. Send Notification
      await prisma.notification.create({
        data: {
          storeId,
          title: "تأكيد الدفع والتفعيل",
          message: `تم مراجعة إيصال الدفع بنجاح. تم تفعيل باقتك (${plan.name}).`,
          type: "BILLING"
        }
      });

    } else if (status === "REJECTED") {
      // Add History
      await prisma.subscriptionHistory.create({
        data: {
          storeId,
          action: "PAYMENT_REJECTED",
          details: `تم رفض إيصال الدفع لطلب رقم ${requestId}`
        }
      });

      // Send Notification
      await prisma.notification.create({
        data: {
          storeId,
          title: "فشل تأكيد الدفع",
          message: `عذراً، تم رفض إيصال الدفع الخاص بك. يرجى مراجعة الدعم أو رفع إيصال واضح.`,
          type: "BILLING"
        }
      });
    }

    revalidatePath("/admin/payment-requests");
    revalidatePath(`/admin/payment-requests/${requestId}`);

    return { success: true };
  } catch (error) {
    console.error("Process Payment Error:", error);
    return { error: "حدث خطأ أثناء معالجة الطلب" };
  }
}

