  try {
    const msg = otpMethod === 'EMAIL' 
      ? `سجل ${user.name} حساباً جديداً بالمنصة (مفعل بالبريد).`
      : otpMethod === 'PHONE'
      ? `سجل ${user.name} حساباً جديداً بالمنصة وتم تفعيل رقمه ${user.phone}.`
      : `سجل ${user.name} حساباً جديداً بالمنصة (بدون تحقق).`;

