import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import { revalidatePath } from "next/cache";

export async function updateOrderStatus(formData: FormData) {
  const session = await auth();
  if (!session?.user?.storeId) return { error: "غير مصرح" };

  const orderId = formData.get("orderId") as string;
  const status = formData.get("status") as any;

  const order = await prisma.order.findUnique({ where: { id: orderId } });

  if (order && order.storeId === session.user.storeId) {
    await prisma.order.update({
      where: { id: orderId },
      data: { status }
    });
    revalidatePath("/dashboard/orders");
  }
}

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { ShoppingBag } from "lucide-react";
import { formatPrice } from "@/lib/utils";
import { Pagination } from "@/components/ui/Pagination";
import { CompactOrderRow } from "@/components/dashboard/CompactOrderRow";

export const metadata = {
  title: "الطلبات | لوحة التحكم",
};

export default async function OrdersPage(props: { searchParams: Promise<{ page?: string }> }) {
  const searchParams = await props.searchParams;
  const page = Number(searchParams.page) || 1;
  const pageSize = 10;

  const session = await auth();

  if (!session?.user?.storeId) {
    return null;
  }

  const [store, totalItems] = await Promise.all([
    prisma.store.findUnique({ where: { id: session.user.storeId } }),
    prisma.order.count({ where: { storeId: session.user.storeId } })
  ]);

  const totalPages = Math.ceil(totalItems / pageSize);

  const orders = await prisma.order.findMany({
    where: { storeId: session.user.storeId },
    orderBy: { createdAt: 'desc' },
    include: {
      items: true,
      branch: true,
      deliveryArea: { include: { governorate: { select: { name: true } } } },
    },
    skip: (page - 1) * pageSize,
    take: pageSize
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between bg-white p-4 rounded-[24px] border-2 border-surface-100">
        <h2 className="text-xl font-bold text-surface-950 px-2">الطلبات الواردة</h2>
      </div>

      <div className="space-y-6">
        {orders.length === 0 ? (
          <div className="text-center py-20 bg-surface-50 border-2 border-surface-100 rounded-[32px]">
            <div className="w-20 h-20 bg-white border-2 border-surface-200 rounded-[24px] flex items-center justify-center mx-auto mb-6">
              <ShoppingBag className="w-10 h-10 text-surface-400" />
            </div>
            <p className="text-xl text-surface-950 font-bold mb-2">لا توجد طلبات حتى الآن.</p>
            <p className="text-surface-500 font-medium">الطلبات الجديدة ستظهر هنا فور استلامها.</p>
          </div>
        ) : (
          <div className="bg-white border-2 border-surface-100 rounded-[32px] overflow-hidden flex flex-col">
            {orders.map(order => (
              <CompactOrderRow key={order.id} order={order} currency={store?.currency} />
            ))}
          </div>
        )}
      </div>

      {totalPages > 1 && (
        <div className="mt-8 flex justify-center">
          <Pagination totalPages={totalPages} />
        </div>
      )}
    </div>
  );
}

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { redirect, notFound } from "next/navigation";
import { OrderMasterDetail } from "../components/OrderMasterDetail";

export const metadata = {
  title: "تفاصيل الطلب | لوحة التحكم",
};

export default async function OrderDetailsPage(props: { params: Promise<{ orderId: string }> }) {
  const params = await props.params;
  const session = await auth();

  if (!session?.user?.storeId) {
    redirect("/login");
  }

  const [store, orders, selectedOrder] = await Promise.all([
    prisma.store.findUnique({ where: { id: session.user.storeId } }),
    prisma.order.findMany({
      where: { storeId: session.user.storeId },
      orderBy: { createdAt: 'desc' },
      take: 50,
      select: {
        id: true,
        orderNumber: true,
        customerName: true,
        status: true,
        createdAt: true,
        total: true,
      }
    }),
    prisma.order.findUnique({
      where: { id: params.orderId, storeId: session.user.storeId },
      include: {
        items: true,
        branch: true,
        deliveryArea: { include: { governorate: { select: { name: true } } } },
      }
    })
  ]);

  if (!store || !selectedOrder) {
    notFound();
  }

  return (
    <OrderMasterDetail 
      orders={orders as any} 
      selectedOrder={selectedOrder as any} 
      currency={store.currency || "SAR"} 
    />
  );
}

