"use server";

import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import { revalidatePath, revalidateTag } from "next/cache";

export async function updateStoreSettings(formData: FormData) {
  const session = await auth();
  if (!session?.user?.storeId) {
    return { error: "غير مصرح لك بالقيام بهذه العملية" };
  }

  // Check if this is a working hours only update
  const isWorkingHoursOnly = formData.get("isWorkingHoursOnly") === "true";

  if (isWorkingHoursOnly) {
    // Build working hours JSON from form data
    const days = ["saturday", "sunday", "monday", "tuesday", "wednesday", "thursday", "friday"];
    const workingHours: Record<string, any> = {};
    
    for (const day of days) {
      workingHours[day] = {
        enabled: formData.get(`wh_${day}_enabled`) === "on",
        allDay: formData.get(`wh_${day}_allDay`) === "on",
        from: formData.get(`wh_${day}_from`) as string || "09:00",
        to: formData.get(`wh_${day}_to`) as string || "23:00",
      };
    }

    try {
      const updatedStore = await prisma.store.update({
        where: { id: session.user.storeId },
        data: { workingHours },
        select: { subdomain: true, domains: { select: { name: true } } }
      });

      revalidatePath("/dashboard/settings");
      if (updatedStore.subdomain) {
        (revalidateTag as any)(`store-${updatedStore.subdomain}`, "default");
      }
      if (updatedStore.domains && updatedStore.domains.length > 0) {
        updatedStore.domains.forEach(d => {
          (revalidateTag as any)(`store-${d.name}`, "default");
        });
      }
      return { success: "تم تحديث مواعيد العمل بنجاح" };
    } catch (error) {
      console.error("Update Working Hours Error:", error);
      return { error: "حدث خطأ أثناء حفظ مواعيد العمل" };
    }
  }

  const name = formData.get("name") as string;
  const description = formData.get("description") as string;
  let logoStr: string | File | null | undefined = formData.get("logo") as string | File | null;
  if (logoStr && typeof logoStr !== "string" && logoStr.size > 0) {
    const { uploadImageToCloudinary } = await import("@/lib/upload");
    try {
      logoStr = await uploadImageToCloudinary(logoStr);
    } catch (e) {
      console.error("Upload error", e);
      return { error: "فشل رفع الصورة" };
    }
  } else if (typeof logoStr !== "string") {
    logoStr = undefined; // Do not update if no new file is provided
  }

  let faviconStr: string | File | null | undefined = formData.get("favicon") as string | File | null;
  if (faviconStr && typeof faviconStr !== "string" && faviconStr.size > 0) {
    const { uploadImageToCloudinary } = await import("@/lib/upload");
    try {
      faviconStr = await uploadImageToCloudinary(faviconStr);
    } catch (e) {
      console.error("Upload error", e);
      return { error: "فشل رفع الأيقونة" };
    }
  } else if (typeof faviconStr !== "string") {
    faviconStr = undefined; // Do not update if no new file is provided
  }

  const primaryColor = formData.get("primaryColor") as string;
  const phone = formData.get("phone") as string;
  const address = formData.get("address") as string;
  const currency = formData.get("currency") as string || "EGP";
  const mapLatitude = formData.get("mapLatitude") as string;
  const mapLongitude = formData.get("mapLongitude") as string;

  if (!name) {
    return { error: "اسم المتجر مطلوب" };
  }

  try {
    const updatedStore = await prisma.store.update({
      where: { id: session.user.storeId },
      data: {
        name,
        description,
        ...(logoStr !== undefined ? { logo: logoStr as string } : {}),
        ...(faviconStr !== undefined ? { favicon: faviconStr as string } : {}),
        primaryColor,
        phone,
        address,
        currency,
        mapLatitude: mapLatitude || null,
        mapLongitude: mapLongitude || null,
      },
      select: { subdomain: true, domains: { select: { name: true } } }
    });

    revalidatePath("/", "layout");
    if (updatedStore.subdomain) {
      revalidatePath(`store-${updatedStore.subdomain}`);
    }
    if (updatedStore.domains) {
      for (const d of updatedStore.domains) {
// @ts-ignore
        revalidatePath(`store-${d.name}`);
      }
    }
    return { success: "تم حفظ الإعدادات الأساسية بنجاح" };
  } catch (error) {
    console.error("Update Store Error:", error);
    return { error: "حدث خطأ أثناء حفظ الإعدادات" };
  }
}

"use server";

import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import { revalidatePath, revalidateTag as _revalidateTag } from "next/cache";

export async function updateSubdomain(formData: FormData) {
  const session = await auth();
  if (!session?.user?.storeId) {
    return { error: "غير مصرح لك بالقيام بهذه العملية" };
  }

  // customDomain logic moved to domain-actions.ts

  let subdomain = formData.get("subdomain") as string;

  if (!subdomain || subdomain.trim() === "") {
    return { error: "يرجى كتابة الرابط أولاً" };
  }

  // Format the subdomain: trim, lowercase, replace spaces with hyphens
  subdomain = subdomain.trim().toLowerCase().replace(/\s+/g, '-');

  // التأكد من صيغة الرابط (أحرف إنجليزية وأرقام وشرطة فقط)
  const regex = /^[a-z0-9-]+$/;
  if (!regex.test(subdomain)) {
    return { error: "الرابط يجب أن يحتوي على أحرف إنجليزية صغيرة وأرقام فقط، وبدون مسافات." };
  }

  try {
    // التحقق من أن الـ subdomain غير مستخدم لمتجر آخر
    const existing = await prisma.store.findUnique({
      where: { subdomain }
    });

    if (existing && existing.id !== session.user.storeId) {
      return { error: "عذراً، هذا الرابط مستخدم من قبل متجر آخر. يرجى اختيار رابط مختلف." };
    }

    const oldStore = await prisma.store.findUnique({
      where: { id: session.user.storeId },
      select: { subdomain: true }
    });

    await prisma.store.update({
      where: { id: session.user.storeId },
      data: { subdomain },
    });

    revalidatePath("/", "layout");
    if (oldStore?.subdomain) {
      revalidatePath(`store-${oldStore.subdomain}`);
    }
    revalidatePath(`store-${subdomain}`);
    return { success: "تم حجز الرابط بنجاح! متجرك الآن متاح عبر هذا الرابط." };
  } catch (error) {
    console.error("Update Subdomain Error:", error);
    return { error: "حدث خطأ أثناء حجز الرابط" };
  }
}

"use server";

import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import { revalidatePath, revalidateTag } from "next/cache";

export async function updateStoreAppearance(formData: FormData) {
  const session = await auth();
  if (!session?.user?.storeId) {
    throw new Error("Unauthorized");
  }

  const fontFamily = formData.get("fontFamily") as string;
  const theme = formData.get("theme") as string;
  const hideProductDescription = formData.get("hideProductDescription") === "true";
  const hideProductAddButton = formData.get("hideProductAddButton") === "true";
  const showFloatingIcons = formData.get("showFloatingIcons") === "true";
  const showBanners = formData.get("showBanners") === "true";
  const showHero = formData.get("showHero") === "true";
  const enableLandingPage = formData.get("enableLandingPage") === "true";
  const landingHeroTitle = formData.get("landingHeroTitle") as string;
  const landingHeroDescription = formData.get("landingHeroDescription") as string;
  const landingHeroOverlayOpacity = parseInt(formData.get("landingHeroOverlayOpacity") as string) || 50;
  
  let landingHeroImage = formData.get("landingHeroImage") as string; // Could be existing URL string

  // Handle new file upload
  const imageFile = formData.get("landingHeroImageFile") as File | null;
  if (imageFile && imageFile.size > 0) {
    const { uploadImageToCloudinary } = await import("@/lib/upload");
    try {
      landingHeroImage = await uploadImageToCloudinary(imageFile) as string;
    } catch (e) {
      console.error("Upload error", e);
      throw new Error("فشل رفع الصورة");
    }
  }

  const store = await prisma.store.update({
    where: { id: session.user.storeId },
    data: { 
      fontFamily, 
      theme, 
      hideProductDescription, 
      hideProductAddButton,
      showFloatingIcons,
      showBanners,
      showHero,
      enableLandingPage,
      landingHeroTitle,
      landingHeroDescription,
      landingHeroImage,
      landingHeroOverlayOpacity
    },
    select: {
      subdomain: true,
      domains: { select: { name: true } }
    }
  });

  // Type assertion for next/cache revalidateTag
  (revalidateTag as any)(`store-info-${session.user.storeId}`, "default");
  if (store.subdomain) {
    (revalidateTag as any)(`store-${store.subdomain}`, "default");
    revalidatePath(`store-${store.subdomain}`);
  }
  if (store.domains) {
    for (const d of store.domains) {
      (revalidateTag as any)(`store-${d.name}`, "default");
      revalidatePath(`store-${d.name}`);
    }
  }

  revalidatePath("/", "layout");
  revalidatePath("/dashboard/appearance");
  
  return { success: true };
}

export async function uploadStoreBanner(formData: FormData) {
  const session = await auth();
  if (!session?.user?.storeId) {
    throw new Error("Unauthorized");
  }

  const imageFiles = formData.getAll("bannerImageFile") as File[];
  if (!imageFiles || imageFiles.length === 0) {
    return { error: "الصور مطلوبة" };
  }

  const { uploadImageToCloudinary } = await import("@/lib/upload");
  try {
    const uploadedBanners = [];
    for (const imageFile of imageFiles) {
      if (imageFile.size === 0) continue;
      const imageUrl = await uploadImageToCloudinary(imageFile) as string;
      const newBanner = await prisma.storeBanner.create({
        data: {
          image: imageUrl,
          storeId: session.user.storeId
        }
      });
      uploadedBanners.push(newBanner);
    }

    const store = await prisma.store.findUnique({ where: { id: session.user.storeId }, select: { subdomain: true, domains: { select: { name: true } } } });
    if (store?.subdomain) {
      (revalidateTag as any)(`store-${store.subdomain}`, "default");
    }
    revalidatePath("/dashboard/settings/appearance");
    
    return { success: true, banners: uploadedBanners };
  } catch (e) {
    console.error("Banner upload error", e);
    return { error: "فشل رفع البانرات" };
  }
}

export async function deleteStoreBanner(bannerId: string) {
  const session = await auth();
  if (!session?.user?.storeId) {
    return { error: "Unauthorized" };
  }

  try {
    await prisma.storeBanner.delete({
      where: { id: bannerId, storeId: session.user.storeId }
    });

    const store = await prisma.store.findUnique({ where: { id: session.user.storeId }, select: { subdomain: true, domains: { select: { name: true } } } });
    if (store?.subdomain) {
      (revalidateTag as any)(`store-${store.subdomain}`, "default");
    }
    revalidatePath("/dashboard/settings/appearance");
    
    return { success: true };
  } catch (e) {
    console.error("Delete banner error", e);
    return { error: "فشل حذف البانر" };
  }
}

