import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import * as xlsx from "xlsx";

export async function GET(req: Request) {
  try {
    const session = await auth();
    if (!session?.user?.id) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    const store = await prisma.store.findUnique({
      where: { id: session.user.storeId as string },
      include: {
        categories: {
          orderBy: { sortOrder: 'asc' },
          include: {
            items: {
              orderBy: { sortOrder: 'asc' },
              include: {
                sizes: true,
                addons: true
              }
            }
          }
        }
      }
    });

    if (!store) {
      return NextResponse.json({ error: "المتجر غير موجود" }, { status: 404 });
    }

    // Prepare Categories Sheet
    const categoriesData = (store as any).categories.length > 0 
      ? (store as any).categories.map((c: any) => ({
          ID: c.id,
          Name: c.name,
          Description: c.description || "",
          SortOrder: c.sortOrder,
          IsActive: c.isActive ? "Yes" : "No"
        }))
      : [{
          ID: "",
          Name: "",
          Description: "",
          SortOrder: "",
          IsActive: ""
        }];

    // Prepare Products Sheet
    const productsData: any[] = [];
    (store as any).categories.forEach((category: any) => {
      category.items.forEach((item: any) => {

        // Format sizes and addons as string
        const sizesStr = item.sizes?.map((s: any) => `${s.name}:${s.price}`).join(" | ") || "";
        const addonsStr = item.addons?.map((a: any) => `${a.name}:${a.price}`).join(" | ") || "";

        productsData.push({
          ID: item.id,
          CategoryID: category.id,
          CategoryName: category.name,
          Name: item.name,
          Description: item.description || "",
          Price: item.price.toString(),
          IsAvailable: item.isAvailable ? "Yes" : "No",
          Image: item.image || "",
          SortOrder: item.sortOrder,
          Sizes: sizesStr,
          Addons: addonsStr
        });
      });
    });

    if (productsData.length === 0) {
      productsData.push({
        ID: "",
        CategoryID: "",
        CategoryName: "",
        Name: "",
        Description: "",
        Price: "",
        IsAvailable: "",
        Image: "",
        SortOrder: "",
        Sizes: "",
        Addons: ""
      });
    }

    // Create a new workbook
    const wb = xlsx.utils.book_new();

    // Add Products Sheet FIRST
    const wsProducts = xlsx.utils.json_to_sheet(productsData);
    xlsx.utils.book_append_sheet(wb, wsProducts, "المنتجات");

    // Add Categories Sheet SECOND
    const wsCategories = xlsx.utils.json_to_sheet(categoriesData);
    xlsx.utils.book_append_sheet(wb, wsCategories, "الأقسام");

    // Write to buffer
    const buf = xlsx.write(wb, { type: 'buffer', bookType: 'xlsx' });

    // Return as downloadable file
    return new Response(buf, {
      status: 200,
      headers: {
        "Content-Disposition": `attachment; filename="menu_${store.subdomain}.xlsx"`,
        "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      }
    });

  } catch (error) {
    console.error("Export Error:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function POST(req: Request) {
  try {
    const session = await auth();
    if (!session?.user?.storeId) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    const { products } = await req.json();

    if (!Array.isArray(products) || products.length === 0) {
      return NextResponse.json({ error: "لا يوجد منتجات للاستيراد" }, { status: 400 });
    }

    const { checkProductLimit } = await import("@/lib/limits");
    const limitCheck = await checkProductLimit(session.user.storeId);
    if (!limitCheck.allowed) {
      return NextResponse.json({ error: "تم الوصول للحد الأقصى للمنتجات" }, { status: 403 });
    }

    const remainingSlots = limitCheck.limit - limitCheck.current;
    if (products.length > remainingSlots) {
      return NextResponse.json({ 
        error: `لا يمكنك استيراد ${products.length} منتج. الباقة تسمح لك بإضافة ${remainingSlots} منتج فقط حالياً.` 
      }, { status: 403 });
    }

    let importedCount = 0;

    for (const item of products) {
      if (!item.name || !item.categoryId) continue;

      // Parse relations
      let sizesObj = {};
      if (item.sizes) {
        const parsed = String(item.sizes).split("|").map(s => {
          const [n, p] = s.split(":");
          return n && p ? { name: n.trim(), price: parseFloat(p) || 0 } : null;
        }).filter(Boolean);
        if (parsed.length) sizesObj = { create: parsed };
      }

      let addonsObj = {};
      if (item.addons) {
        const parsed = String(item.addons).split("|").map(s => {
          const [n, p] = s.split(":");
          return n && p ? { name: n.trim(), price: parseFloat(p) || 0 } : null;
        }).filter(Boolean);
        if (parsed.length) addonsObj = { create: parsed };
      }

      // Upsert logic
      if (item.id && item.id.length > 5) {
        // Try update if ID exists
        try {
          // Delete old relations first if doing update
          await prisma.menuItemSize.deleteMany({ where: { menuItemId: item.id } }).catch(() => {});
          await prisma.menuItemAddon.deleteMany({ where: { menuItemId: item.id } }).catch(() => {});

          await prisma.menuItem.update({
            where: { id: item.id, storeId: session.user.storeId },
            data: {
              name: item.name,
              description: item.description,
              price: item.price,
              categoryId: item.categoryId,
              image: item.image,
              sortOrder: item.sortOrder,
              isAvailable: item.isActive,
              sizes: sizesObj,
              addons: addonsObj
            }
          });
          importedCount++;
          continue;
        } catch (e) {
          // If update fails, fallback to create
        }
      }

      // Create new
      await prisma.menuItem.create({
        data: {
          storeId: session.user.storeId,
          name: item.name,
          description: item.description,
          price: item.price,
          categoryId: item.categoryId,
          image: item.image,
          sortOrder: item.sortOrder,
          isAvailable: item.isActive,
          sizes: sizesObj,
          addons: addonsObj
        }
      });
      importedCount++;
    }

    return NextResponse.json({ success: true, count: importedCount });

  } catch (error: any) {
    console.error("Confirm import error:", error);
    return NextResponse.json({ error: error.message || "حدث خطأ أثناء الحفظ" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import * as xlsx from "xlsx";
import { v4 as uuidv4 } from "uuid";

export async function POST(req: Request) {
  try {
    const session = await auth();
    if (!session?.user?.storeId) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    const formData = await req.formData();
    const file = formData.get("file") as File;
    if (!file) {
      return NextResponse.json({ error: "لم يتم العثور على ملف" }, { status: 400 });
    }

    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);
    const wb = xlsx.read(buffer, { type: 'buffer' });

    const productsSheetName = wb.SheetNames.includes("Products") ? "Products" : (wb.SheetNames.includes("المنتجات") ? "المنتجات" : null);

    if (!productsSheetName) {
      return NextResponse.json({ error: "لم يتم العثور على ورقة المنتجات (Products/المنتجات)" }, { status: 400 });
    }

    const wsProducts = wb.Sheets[productsSheetName];
    const productsData = xlsx.utils.sheet_to_json<any>(wsProducts);

    // Fetch existing categories
    const storeCategories = await prisma.category.findMany({
      where: { storeId: session.user.storeId },
      select: { id: true, name: true }
    });

    // Fetch existing items to check for duplicates
    const existingItems = await prisma.menuItem.findMany({
      where: { storeId: session.user.storeId },
      select: { name: true, price: true }
    });

    const parsedProducts = [];
    let duplicateCount = 0;

    for (const row of productsData) {
      if (!row.Name) continue;

      const price = parseFloat(row.Price) || 0;

      // Check for exact duplicate in DB
      const isDuplicate = existingItems.some(item => 
        item.name.toLowerCase().trim() === row.Name.toLowerCase().trim() && 
        Number(item.price) === price
      );

      if (isDuplicate) duplicateCount++;

      // Try to find matching category by Name if possible
      const categoryName = row.CategoryName || "";
      let categoryId = "";
      if (categoryName) {
        const matchingCat = storeCategories.find(c => c.name.toLowerCase() === categoryName.toLowerCase());
        if (matchingCat) categoryId = matchingCat.id;
      }

      parsedProducts.push({
        tempId: uuidv4(),
        id: row.ID || undefined,
        name: row.Name,
        description: row.Description || "",
        price: price,
        categoryName: categoryName,
        categoryId: categoryId, // will be empty if not found, forcing user to select
        image: row.Image || "",
        sortOrder: parseInt(row.SortOrder) || 0,
        isActive: row.IsActive === "Yes" || row.IsActive === "نعم",
        sizes: row.Sizes || "",
        addons: row.Addons || "",
        isDuplicate,
        selected: !isDuplicate // default select if not duplicate
      });
    }

    return NextResponse.json({
      success: true,
      products: parsedProducts,
      categories: storeCategories,
      duplicateCount
    });

  } catch (error: any) {
    console.error("Preview import error:", error);
    return NextResponse.json({ error: error.message || "حدث خطأ أثناء تحليل الملف" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { auth } from "@/lib/auth";
import * as xlsx from "xlsx";

export async function POST(req: Request) {
  try {
    const session = await auth();
    if (!session?.user?.id) {
      return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
    }

    const store = await prisma.store.findUnique({
      where: { id: session.user.storeId as string }
    });

    if (!store) {
      return NextResponse.json({ error: "المتجر غير موجود" }, { status: 404 });
    }

    const formData = await req.formData();
    const file = formData.get("file") as File | null;

    if (!file) {
      return NextResponse.json({ error: "لم يتم رفع أي ملف" }, { status: 400 });
    }

    // Read the file as buffer
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Parse the excel file
    const wb = xlsx.read(buffer, { type: 'buffer' });

    let importedCount = 0;

    // Process Categories Sheet
    const categoriesSheetName = wb.SheetNames.includes("Categories") ? "Categories" : (wb.SheetNames.includes("الأقسام") ? "الأقسام" : null);
    if (categoriesSheetName) {
      const wsCategories = wb.Sheets[categoriesSheetName];
      const categoriesData = xlsx.utils.sheet_to_json<any>(wsCategories);

      for (const row of categoriesData) {
        if (!row.Name) continue; // Skip invalid rows

        await prisma.category.upsert({
          where: { id: row.ID || "new-temp-id" }, // Using a fake id to force create if no ID
          update: {
            name: row.Name,
            sortOrder: parseInt(row.SortOrder) || 0,
            description: row.Description || null,
          },
          create: {
            id: row.ID || undefined, // use provided ID or let prisma generate
            storeId: store.id,
            name: row.Name,
            sortOrder: parseInt(row.SortOrder) || 0,
            description: row.Description || null,
          }
        }).catch(e => {
          // If upsert fails on ID not found (sometimes happens), we can try to find first or create
          // Actually prisma upsert with a fake ID will fail if the ID is not found for update?
          // No, if the WHERE condition is not met, it will CREATE. 
          console.error("Category Import Error for row", row, e);
        });
        importedCount++;
      }
    }

    // Process Products Sheet
    const productsSheetName = wb.SheetNames.includes("Products") ? "Products" : (wb.SheetNames.includes("المنتجات") ? "المنتجات" : null);
    if (productsSheetName) {
      const { checkProductLimit } = await import("@/lib/limits");

      const wsProducts = wb.Sheets[productsSheetName];
      const productsData = xlsx.utils.sheet_to_json<any>(wsProducts);

      for (const row of productsData) {
        if (!row.Name || !row.CategoryID) continue;

        // Check limits before creating a new product
        if (!row.ID) { // If it's a new product (doesn't have an ID)
          const { allowed } = await checkProductLimit(store.id);
          if (!allowed) {
            console.warn(`Reached product limit for store ${store.id}, stopping import`);
            break; // Stop importing more products
          }
        }

        // Verify category exists
        const category = await prisma.category.findFirst({
          where: { id: row.CategoryID, storeId: store.id }
        });

        if (!category) continue; // Skip if category is invalid

        // Parse Sizes
        const parsedSizes = [];
        if (row.Sizes) {
          const sizeParts = row.Sizes.toString().split('|');
          for (const p of sizeParts) {
            const [name, price] = p.split(':');
            if (name && price) {
              parsedSizes.push({ name: name.trim(), price: parseFloat(price.trim()) || 0 });
            }
          }
        }

        // Parse Addons
        const parsedAddons = [];
        if (row.Addons) {
          const addonParts = row.Addons.toString().split('|');
          for (const p of addonParts) {
            const [name, price] = p.split(':');
            if (name && price) {
              parsedAddons.push({ name: name.trim(), price: parseFloat(price.trim()) || 0 });
            }
          }
        }

        await prisma.menuItem.upsert({
          where: { id: row.ID || "new-temp-id" },
          update: {
            name: row.Name,
            description: row.Description || null,
            price: parseFloat(row.Price) || 0,
            isAvailable: row.IsAvailable === "Yes",
            image: row.Image || null,
            sortOrder: parseInt(row.SortOrder) || 0,
            categoryId: category.id,
            storeId: store.id,
            // Sizes and Addons update: first delete old, then create new
            sizes: { deleteMany: {}, create: parsedSizes },
            addons: { deleteMany: {}, create: parsedAddons }
          },
          create: {
            id: row.ID || undefined,
            name: row.Name,
            description: row.Description || null,
            price: parseFloat(row.Price) || 0,
            isAvailable: row.IsAvailable === "Yes",
            image: row.Image || null,
            sortOrder: parseInt(row.SortOrder) || 0,
            categoryId: category.id,
            storeId: store.id,
            sizes: { create: parsedSizes },
            addons: { create: parsedAddons }
          }
        }).catch(e => console.error("Product Import Error for row", row, e));
        importedCount++;
      }
    }

    return NextResponse.json({ success: true, count: importedCount });

  } catch (error) {
    console.error("Import Error:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { auth } from "@/lib/auth";
