"use server";

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { redirect } from "next/navigation";
import { slugifyArabic } from "@/lib/slugify";

export async function submitStep1(formData: FormData) {
  const session = await auth();
  if (!session?.user?.id) return { error: "غير مصرح" };

  const name = formData.get("name") as string;
  const primaryColor = formData.get("primaryColor") as string;
  let logoStr: string | File | null | undefined = formData.get("logo") as string | File | null;

  if (logoStr && typeof logoStr !== "string" && logoStr.size > 0) {
    const { uploadImageToCloudinary } = await import("@/lib/upload");
    try {
      logoStr = await uploadImageToCloudinary(logoStr);
    } catch (e) {
      return { error: "فشل رفع الصورة" };
    }
  } else if (typeof logoStr !== "string") {
    logoStr = undefined;
  }

  const baseSlug = slugifyArabic(name) || "store";
  let subdomain = baseSlug;
  let counter = 0;
  while (true) {
    const existing = await prisma.store.findUnique({ where: { subdomain } });
    if (!existing || existing.userId === session.user.id) break;
    counter++;
    subdomain = `${baseSlug}-${String.fromCharCode(96 + counter)}`;
  }

  await prisma.store.update({
    where: { userId: session.user.id },
    data: {
      name,
      primaryColor,
      ...(logoStr !== undefined ? { logo: logoStr as string } : {}),
      subdomain,
    }
  });

  await prisma.user.update({
    where: { id: session.user.id },
    data: { onboardingStep: 2 }
  });

  redirect("/onboarding?step=2");
}

export async function skipStep(step: number) {
  const session = await auth();
  if (!session?.user?.id) return;

  if (step === 1) {
    const randomSuffix = Math.floor(100000 + Math.random() * 900000);
    const subdomain = `store-${randomSuffix}`;
    await prisma.store.update({
      where: { userId: session.user.id },
      data: { subdomain }
    });
  }

  await prisma.user.update({
    where: { id: session.user.id },
    data: { onboardingStep: step + 1 }
  });

  if (step === 3) {
    redirect("/dashboard");
  } else {
    redirect(`/onboarding?step=${step + 1}`);
  }
}

export async function submitStep2(formData: FormData) {
  const session = await auth();
  if (!session?.user?.id) return { error: "غير مصرح" };

  const phone = formData.get("phone") as string;
  const whatsappNumber = formData.get("whatsappNumber") as string;
  const address = formData.get("address") as string;

  await prisma.store.update({
    where: { userId: session.user.id },
    data: { phone, whatsappNumber, address }
  });

  await prisma.user.update({
    where: { id: session.user.id },
    data: { onboardingStep: 3 }
  });

  redirect("/onboarding?step=3");
}

export async function finishOnboarding() {
  const session = await auth();
  if (!session?.user?.id) return;

  await prisma.user.update({
    where: { id: session.user.id },
    data: { onboardingStep: 4 } // mark as finished
  });

  redirect("/dashboard");
}

import { auth } from "@/lib/auth";
import { redirect } from "next/navigation";
import { prisma } from "@/lib/prisma";
import { OnboardingClient } from "./client";
import { PageTransitionLoader } from "@/components/ui/PageTransitionLoader";

export default async function OnboardingPage({ searchParams }: { searchParams: Promise<{ step?: string }> }) {
  const { step } = await searchParams;
  const session = await auth();
  if (!session || session.user.role !== "OWNER") {
    redirect("/login");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
    include: { store: true }
  });

  if (!user) {
    redirect("/login");
  }

  if (user.onboardingStep >= 4 && step !== "4") {
    redirect("/dashboard");
  }

  const currentStep = step ? parseInt(step) : (user.store ? user.onboardingStep : 1);

  // We should force the step to be at max the user's allowed step to prevent skipping via URL
  const actualStep = Math.min(currentStep, user.onboardingStep || 1);

  return (
    <div className="min-h-screen bg-surface-50 flex flex-col items-center justify-center p-4 py-4" dir="rtl">
      <div className="w-full max-w-lg bg-white rounded-[2rem] overflow-hidden animate-fade-in border border-surface-200">
        <div className="p-4 md:p-6">
          <OnboardingClient 
            step={actualStep} 
            storeName={user.store?.name || ""} 
            subdomain={user.store?.subdomain || ""} 
          />
        </div>
      </div>
    </div>
  );
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ storeId: string }> }
) {
  const { storeId } = await params;

  if (!storeId) {
    return NextResponse.redirect(new URL("/", request.url));
  }

  try {
    const store = await prisma.store.findUnique({
      where: { id: storeId },
      include: { domains: true },
    });

    if (!store) {
      return NextResponse.redirect(new URL("/", request.url));
    }

    // Determine the active domain or subdomain
    let redirectUrl = "";

    if (store.domains && store.domains.length > 0 && store.domains[0].name) {
      redirectUrl = `https://${store.domains[0].name}`;
    } else if (store.subdomain) {
      redirectUrl = `https://${store.subdomain}.almenu.pro`;
    } else {
      // Fallback
      redirectUrl = `https://${store.id}.almenu.pro`;
    }

    return NextResponse.redirect(redirectUrl);
  } catch (error) {
    console.error("QR Redirect Error:", error);
    return NextResponse.redirect(new URL("/", request.url));
  }
}

